// word-frequency (js entry) -- count 3,000,000 picks from a 64-word
// vocabulary generated by a pinned integer LCG, then fold the counts into one
// deterministic checksum.
//
// Run: node main.mjs
//
// Same workload and same output in every language entry. This is the
// hash-map-shaped task: every pick is a string-keyed lookup + increment, and
// the final fold walks the vocabulary in a fixed order so no language's map
// iteration order can leak into the output.

const CORPUS = 3000000;
const VOCAB = 64;

const words = [];
for (let i = 0; i < VOCAB; i++) {
  words.push("word" + String(i).padStart(2, "0"));
}

const counts = new Map();

let state = 1;
for (let k = 0; k < CORPUS; k++) {
  state = (state * 48271) % 2147483647;
  const word = words[state % VOCAB];
  counts.set(word, (counts.get(word) ?? 0) + 1);
}

let checksum = 0;
for (const word of words) {
  checksum = (checksum * 31 + (counts.get(word) ?? 0)) % 1000000007;
}
console.log(checksum);
